from collections import deque

def take_many(queue, count):
    result = []
    while queue and len(result) < count:
        result.append(queue.popleft())
    return result

for values, count in [([], 3), ([1, 2, 3], 2), ([None, 1], 5)]:
    queue = deque(values)
    print(take_many(queue, count), list(queue))

from collections import deque

def serve_requests(actions):
    queue = deque()
    replies = []
    for action, value in actions:
        if action == "add":
            queue.append(value)
        elif queue:
            replies.append((True, queue.popleft()))
        else:
            replies.append((False, None))
    return replies, list(queue)

print(serve_requests([]))
print(serve_requests([("add", None), ("next", None), ("next", None)]))
print(serve_requests([("add", "A"), ("add", "B"), ("next", None), ("add", "C")]))

from collections import deque

def palindrome_deque(values):
    pending = deque(values)
    while len(pending) > 1:
        if pending.popleft() != pending.pop():
            return False
    return True

for values in [[], [7], [1, 2, 1], [1, 2, 2]]:
    print(palindrome_deque(values))

from collections import deque

def rotate_left(values, count):
    pending = deque(values)
    if not pending:
        return []
    for _ in range(count % len(pending)):
        pending.append(pending.popleft())
    return list(pending)

print(rotate_left([], 7))
print(rotate_left([1, 2, 3], 1))
print(rotate_left([1, 1, 2], 4))
